NAV=[('/', 'Application lab'),('/learn.html','What you will learn'),('/run.html','How to run'),('/architecture.html','Architecture & workflow'),('/walkthrough.html','Code walkthrough')]
def document(path,title,subtitle,body,extra=''):
 nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if url==path else '')+'>'+label+'</a>' for url,label in NAV)
 html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agent SDK S01 · '+escape(title)+'</title><link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/code-highlighting.css"></head><body><main><div class="brand"><a href="/">How <span>Claude Agent SDK</span> Works</a><span class="badge">LESSON S01 / QUERY()</span></div><header class="hero"><div><div class="eyebrow">YOUR FIRST CLAUDE AGENT SDK APPLICATION</div><h1>'+title+'</h1><p class="lead">'+subtitle+'</p></div><img src="/astronaut.png" alt="Course astronaut mascot"></header><nav class="nav" aria-label="Application sections">'+nav+'<button id="theme" type="button">Dark mode</button></nav>'+body+'<footer>CLAUDE AGENT SDK · S01 · ONE QUERY, ONE OBSERVED RESULT<br>TypeScript · local runtime · API key stays on the server</footer></main><script src="/navigation.js"></script><script src="/prism.js"></script><script src="/code-highlighting.js"></script>'+extra+'</body></html>'
 (PUBLIC/('index.html' if path=='/' else path[1:])).write_text(html,encoding='utf-8')
def snippet(value,lang='typescript'):return '<pre><code class="language-'+lang+'">'+escape(value)+'</code></pre>'
def cards(items):return '<div class="grid">'+''.join(f'<article class="card"><span class="number">{i:02}</span><h3>{escape(a)}</h3><p>{escape(b)}</p></article>' for i,(a,b) in enumerate(items,1))+'</div>'
def actions(previous,next):return '<div class="actions">'+''.join(f'<a class="button" href="{p}">{t}</a>' for p,t in [previous,next])+'</div>'

document('/','Start with <em>query().</em>','A prompt goes in. SDK messages come back. Observe the assistant text and the final result, one step at a time.',
 '<div class="flow"><div><b>01 · Prompt</b><p>Describe a small task</p></div><span>→</span><div><b>02 · query()</b><p>The SDK runs locally</p></div><span>→</span><div><b>03 · Observe</b><p>Read the final result</p></div></div><section class="workspace"><article class="panel"><p class="eyebrow">YOUR FIRST QUERY</p><h2>Ask one question</h2><p id="configuration" class="meta" role="status">Checking local configuration…</p><form id="form"><label for="prompt">Prompt</label><textarea id="prompt" maxlength="2000" required></textarea><p class="meta">Model: <strong id="model">—</strong><br>Tools: none · Turn limit: 1 · Per-run SDK budget: $0.10</p><button class="primary" id="run" disabled>Run query() →</button></form><p class="meta">Each click starts a fresh SDK query. The result cost is an estimate; the budget is not a price quote.</p><a href="/run.html">Need help configuring the app?</a></article><article class="panel"><p class="eyebrow">REAL SDK OUTPUT</p><h2>Inspect the answer</h2><div class="stats"><div class="stat"><span>Status</span><strong id="status" role="status">Ready</strong></div><div class="stat"><span>Turns</span><strong id="turns">—</strong></div><div class="stat"><span>Estimated cost</span><strong id="cost">—</strong></div></div><div id="answer" aria-live="polite"></div><p class="meta">SDK session ID: <span id="session">—</span></p><details open><summary>Walk through the message sequence</summary><ol id="events"></ol></details></article></section><aside class="note">This is the <strong>Claude Agent SDK</strong>: its runtime runs on this computer and calls Claude. This lesson uses no tools, custom agents, MCP servers or Managed Agents resources. Assistant text alone does not mark completion; inspect the final SDK result. Wait for the result before navigating away: closing this page cancels this app’s local run.</aside>'+actions(('/learn.html','What you will learn →'),('/architecture.html','Explore the architecture →')), '<script type="module" src="/client.js"></script>')

learning=[('One SDK entry point','Import query from @anthropic-ai/claude-agent-sdk. No agent class or create-agent API is required for this example.'),('An async message iterator','query() returns an async iterator. for await...of receives messages as the SDK runtime works.'),('A prompt and explicit options','The prompt describes the task. The model and options define the small teaching experiment.'),('Assistant text versus final result','Read text content from assistant messages. Check result.subtype and is_error before reporting success.'),('A local runtime and cloud model','The Agent SDK starts its runtime on the host. Claude model inference happens through the configured API provider.'),('Configuration and observable evidence','Load .env on startup, keep the key server-side, and compare the status, turns and estimated cost with the event list.')]
document('/learn.html','What you <em>will learn.</em>','Understand the smallest useful Agent SDK application before adding tools or multi-turn workflows.',cards(learning)+'<section class="step"><h2>What you will build</h2><p>A TypeScript web app and a terminal command that share the same small agent function. You submit a text prompt, observe the SDK messages, and inspect the final outcome.</p><h3>Agent SDK and Managed Agents are different surfaces</h3><div class="table"><table><tr><th>This Agent SDK lab</th><th>The earlier Managed Agents labs</th></tr><tr><td>Call <code>query()</code> on the host.</td><td>Use the Managed Agents agent/environment/session APIs.</td></tr><tr><td>The SDK launches a local Claude runtime.</td><td>The service manages remote agent execution.</td></tr><tr><td>No agent or environment IDs are needed.</td><td>Sessions select reusable managed resources.</td></tr><tr><td>This sample disables tools and session persistence.</td><td>Capabilities and retained remote history depend on the managed configuration.</td></tr></table></div></section><section class="note"><strong>Try to explain it yourself:</strong> Why is query() not a Promise of a single string? Which message establishes the final outcome? What changes if the answer text arrives but the stream ends without a result?</section>'+actions(('/','← Application lab'),('/run.html','Configure and run →')))

install='cd .\\agent-sdk\\lesson-s01-query\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3101'
run='<section class="step"><span class="number">01</span><h2>Check the prerequisites</h2><p>Use Node.js 24 or newer, npm, and an Anthropic API key with access to the model you select. On Windows, install Git for Windows if the SDK asks for Git Bash. The pinned SDK installs its Claude runtime through an optional platform package; keep optional dependencies enabled.</p>'+snippet('node --version\nnpm --version','powershell')+'</section>'
run+='<section class="step"><span class="number">02</span><h2>Install and create your .env file</h2><p>From the <code>presentations</code> directory, run the commands below. If you cloned this application from GitHub, start in the repository root and skip the first cd command. Preserve an existing .env rather than overwriting it.</p>'+snippet(install,'powershell')+'<p>Enter your own key in .env. This is a safe template, not a real credential:</p>'+snippet(env,'dotenv')+'<p>No Managed Agents agent ID or environment ID is required. Select a model available to your account. The SDK does not load .env itself; the npm scripts use Node’s <code>--env-file-if-exists=.env</code> startup option.</p></section>'
run+='<section class="step"><span class="number">03</span><h2>Windows: resolve Git Bash if needed</h2><p>If the runtime cannot find Git Bash, add its actual executable path to .env. A common installation is:</p>'+snippet('CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe','dotenv')+'<p>If the runtime binary is missing after installation, run <code>npm ci</code> without <code>--omit=optional</code>. No separate global Claude installation is normally needed for this pinned SDK on supported platforms.</p></section>'
run+='<section class="step"><span class="number">04</span><h2>Start the application</h2>'+snippet('npm start','powershell')+'<p>Keep the terminal running and open <a href="http://127.0.0.1:3101">http://127.0.0.1:3101</a>. Use the address printed by the server if you change PORT. Restart after editing .env. The server becoming ready does not perform a model call.</p></section>'
run+='<section class="step"><span class="number">05</span><h2>Run your first real query</h2><ol><li>Open <a href="/">Application lab</a> and confirm the server reports a configured key.</li><li>Keep the default prompt or enter a short question.</li><li>Press <strong>Run query()</strong> once.</li><li>Read the initialized event, assistant text and final result.</li><li>Confirm <strong>Success</strong>, one turn and an estimated cost. A final error outcome remains an error even if some text arrived.</li></ol><p>Each click may incur API usage. This sample has no tool execution, no session resume and no transcript persistence. It permits one run at a time and aborts a run after 90 seconds or when its browser connection closes.</p></section>'
run+='<section class="step"><span class="number">06</span><h2>Run the same agent in the terminal</h2>'+snippet('npm run agent -- "Explain an AI agent in one sentence."\n\n# Check types and local message handling (no API call):\nnpm test\n\n# Only after editing src/client.ts:\nnpm run build:client','powershell')+'<p>The web and terminal versions both use <code>src/agent.ts</code>. npm start uses the prepared browser asset, so it does not rebuild the project each time.</p></section>'
run+='<section class="step"><h2>Troubleshooting</h2><div class="table"><table><tr><th>Symptom</th><th>What to check</th></tr><tr><td>Setup needed</td><td>Save a real ANTHROPIC_API_KEY in .env and restart npm start.</td></tr><tr><td>Authentication or model error</td><td>Check key validity, billing and access to CLAUDE_MODEL in your account.</td></tr><tr><td>Runtime or Git Bash not found</td><td>Keep optional npm dependencies enabled. Check the Windows path above.</td></tr><tr><td>Turn or budget limit</td><td>Use a shorter text-only prompt. The final subtype explains the limit; it is not success.</td></tr><tr><td>Port in use</td><td>If this app is already running, open its printed URL. To restart after edits, press Ctrl+C in the original terminal first. For a different service, stop it or choose another PORT in .env.</td></tr><tr><td>Browser cannot connect</td><td>The local terminal must remain running. Use 127.0.0.1 and the configured port.</td></tr></table></div></section>'
document('/run.html','Configure and <em>run the app.</em>','Follow these steps from installation to your first observed SDK result.',run+actions(('/learn.html','← Learning goals'),('/','Open the application lab →')))

